CREATE OR REPLACE FUNCTION public.agent_chat_photos_expired(p_older_than interval DEFAULT NULL::interval, p_limit integer DEFAULT 500)
 RETURNS TABLE(name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select o.name
    from storage.objects o
   where o.bucket_id = 'agent-chat-photos'
     and o.created_at < now() - greatest(coalesce(p_older_than, private.agent_chat_photo_retention()), interval '1 hour')
     and not exists (select 1 from private.media_rewrite_claims r
                      where r.bucket = 'agent-chat-photos' and r.path = o.name
                        and r.claimed_at > now() - interval '10 minutes')
   order by o.created_at
   limit greatest(1, least(coalesce(p_limit, 500), 1000));
$function$;

grant execute on function public.agent_chat_photos_expired(p_older_than interval, p_limit integer) to service_role;
